from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
links=set()
for page in r.pages:
 for annotation in page.get('/Annots',[]):
  item=annotation.get_object()
  action=item.get('/A',{})
  if hasattr(action,'get_object'): action=action.get_object()
  if action.get('/URI'): links.add(str(action['/URI']))
print('\\n'.join(sorted(links)))
PY"
